	private MapBindingSet serviceRow(String endpoint) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("service", repository.getValueFactory().createIRI(endpoint));
		return row;
	}

	private BindingSetAssignment serviceValues(BindingSet... rows) {
		BindingSetAssignment provider = new BindingSetAssignment();
		provider.setBindingNames(Set.of("service"));
		provider.setBindingSets(List.of(rows));
		return provider;
	}

	private LeftJoin localServiceOptional(TupleExpr provider, String shape, boolean silent, String endpoint) {
		TupleExpr right = filteredService(silent, endpoint);
		if (shape.equals("join")) {
			right = new Join(new SingletonSet(), right);
		} else if (shape.equals("union")) {
			right = new Union(right, filteredService(silent, endpoint));
		}
		return new LeftJoin(provider, right);
	}

