	@Test
	public void scopedJoinAndOptionalUseOnlyTheirActualGraphCarrier() {
		var vf = repository.getValueFactory();
		IRI subject = vf.createIRI("urn:carrier:subject");
		IRI predicate = vf.createIRI("urn:carrier:predicate");
		IRI object = vf.createIRI("urn:carrier:object");
		IRI graph = vf.createIRI("urn:carrier:graph");
		IRI other = vf.createIRI("urn:carrier:other");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object, graph);
		}
		List<Executable> checks = new ArrayList<>();
		for (boolean optional : List.of(false, true)) {
			MapBindingSet matching = new MapBindingSet();
			matching.addBinding("selector", graph);
			matching.addBinding("witness", vf.createLiteral(1));
			MapBindingSet conflicting = new MapBindingSet();
			conflicting.addBinding("selector", other);
			conflicting.addBinding("witness", vf.createLiteral(1));
			BindingSetAssignment carrier = new BindingSetAssignment();
			carrier.setBindingNames(Set.of("selector", "witness"));
			carrier.setBindingSets(List.of(matching, matching, conflicting));
			Var privateGraph = Var.of("privateGraph", graph);
			privateGraph.setGraphContextDepth(1);
			StatementPattern statement = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("s"),
					Var.of("p", predicate, true, true), Var.of("o", object, true, true), privateGraph);
			Projection inner = new Projection(statement, new ProjectionElemList(new ProjectionElem("s")), true);
			inner.setProjectionContext(Var.of("selector"));
			inner.setInheritedGraphParameter("privateGraph");
			Filter dependent = new Filter(inner, new Bound(Var.of("witness")));
			dependent.setConditionBindingScope(Filter.ConditionBindingScope.ALL);
			BinaryTupleOperator expression = optional ? new LeftJoin(carrier, dependent) : new Join(carrier, dependent);
			MapBindingSet hidden = new MapBindingSet();
			hidden.addBinding("selector", other);
			MapBindingSet matched = new MapBindingSet();
			matched.addBinding("selector", graph);
			matched.addBinding("witness", vf.createLiteral(1));
			matched.addBinding("s", subject);
			List<BindingSet> expected = optional ? List.of(matched, matched, conflicting) : List.of(matched, matched);
			checks.add(() -> assertEquals(expected,
					evaluateWithHiddenProbe(expression, EmptyBindingSet.getInstance(), hidden),
					"optional=" + optional));
			checks.add(() -> assertEquals("ScopedCorrelatedJoinIterator", expression.getAlgorithmName(),
					"the actual carrier is forwarded through the scoped iterator"));
		}
		assertAll(checks);
	}

