	@Test
	public void fixedInheritedGraphHonorsApiSelectorAndAuthorizedFrameOnly() {
		var vf = repository.getValueFactory();
		IRI subject = vf.createIRI("urn:graph-authority:subject");
		IRI predicate = vf.createIRI("urn:graph-authority:predicate");
		IRI object = vf.createIRI("urn:graph-authority:object");
		IRI graph = vf.createIRI("urn:graph-authority:graph");
		IRI other = vf.createIRI("urn:graph-authority:other");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object, graph);
		}
		MapBindingSet local = new MapBindingSet();
		local.addBinding("g", subject);
		MapBindingSet expected = new MapBindingSet();
		expected.addBinding("local", subject);
		Projection matchingApi = fixedGraphWithLocalSubject(predicate, object, graph, "selector",
				Var.of("selector", graph).withApiInputOrigin());
		Projection conflictingApi = fixedGraphWithLocalSubject(predicate, object, graph, "selector",
				Var.of("selector", other).withApiInputOrigin());
		Projection framed = fixedGraphWithLocalSubject(predicate, object, graph, "privateGraph", Var.of("selector"));
		framed.setInheritedGraphParameter("privateGraph");
		MutableBindingSet matchingFrame = GraphFrameBindings.supply(new QueryBindingSet(local), "privateGraph", graph);
		MutableBindingSet conflictingFrame = GraphFrameBindings.supply(new QueryBindingSet(local), "privateGraph",
				other);
		MutableBindingSet matchingSelector = GraphFrameBindings.supply(new QueryBindingSet(local), "selector", graph);
		MutableBindingSet conflictingSelector = GraphFrameBindings.supply(new QueryBindingSet(local), "selector",
				other);
		QueryBindingSet spoof = new QueryBindingSet(local);
		spoof.addBinding("privateGraph", other);
		QueryBindingSet matchingSpoof = new QueryBindingSet(local);
		matchingSpoof.addBinding("privateGraph", graph);
		MapBindingSet hiddenSelector = new MapBindingSet();
		hiddenSelector.addBinding("selector", other);
		assertAll(
				() -> assertEquals(List.of(expected), evaluateDirect(matchingApi.clone(), local),
						"matching API selector"),
				() -> assertEquals(List.of(), evaluateDirect(conflictingApi.clone(), local),
						"conflicting API selector"),
				() -> assertEquals(List.of(expected), evaluateOptimizedDirect(matchingApi.clone(), local),
						"optimized matching API selector"),
				() -> assertEquals(List.of(), evaluateOptimizedDirect(conflictingApi.clone(), local),
						"optimized conflicting API selector"),
				() -> assertEquals(List.of(expected), evaluateDirect(framed.clone(), matchingFrame), "matching frame"),
				() -> assertEquals(List.of(), evaluateDirect(framed.clone(), conflictingFrame), "conflicting frame"),
				() -> assertEquals(List.of(expected), evaluateDirect(framed.clone(), matchingSelector),
						"matching supplied selector"),
				() -> assertEquals(List.of(), evaluateDirect(framed.clone(), conflictingSelector),
						"conflicting supplied selector"),
				() -> assertEquals(List.of(expected), evaluateDirect(framed.clone(), spoof),
						"untrusted conflicting alias"),
				() -> assertEquals(List.of(expected), evaluateDirect(framed.clone(), matchingSpoof),
						"untrusted matching alias"),
				() -> assertEquals(List.of(expected), evaluateWithHiddenProbe(framed.clone(), local, hiddenSelector),
						"hidden selector probe is not graph authority"));
	}

