	private static Projection fixedGraphWithLocalSubject(IRI predicate, IRI object, IRI graph,
			String graphName, Var selector) {
		Var inherited = Var.of(graphName, graph);
		inherited.setGraphContextDepth(1);
		StatementPattern statement = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("g"),
				Var.of("p", predicate, true, true), Var.of("o", object, true, true), inherited);
		Projection projection = new Projection(statement, new ProjectionElemList(new ProjectionElem("g", "local")),
				true);
		projection.setProjectionContext(selector);
		return projection;
	}

	private List<BindingSet> evaluateWithHiddenProbe(TupleExpr expression, BindingSet logical, BindingSet probe) {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingFrameBindings.Scope owner = new BindingFrameBindings.Scope();
		try (BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null)) {
			invocation.root.registerLookupInputs(owner, name -> true);
			return evaluateDirect(expression,
					BindingFrameBindings.push(owner, logical, probe, context, invocation.root));
		}
	}

