		IRI other = vf.createIRI("urn:local-graph:other");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object, graph);
		}
		StatementPattern statement = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("s"),
				Var.of("p", predicate, true, true), Var.of("o", object, true, true), Var.of("g", graph));
		Projection local = new Projection(statement, new ProjectionElemList(new ProjectionElem("s")), true);
		MapBindingSet expected = new MapBindingSet();
		expected.addBinding("s", subject);
		MapBindingSet matching = new MapBindingSet();
		matching.addBinding("g", graph);
