	private StatementPattern valuedServiceStatement(String position) {
		return serviceStatement(position, false);
	}

	private StatementPattern serviceStatement(String position, boolean queryConstant) {
		var vf = repository.getValueFactory();
		Var subject = Var.of("subject", vf.createIRI("urn:subject"), true, true);
		Var predicate = Var.of("predicate", vf.createIRI("urn:predicate"), true, true);
		Var object = Var.of("object", vf.createIRI("urn:object"), true, true);
		Var endpoint = Var.of("service", vf.createIRI("urn:fail:valued-endpoint"), queryConstant, queryConstant);
		return switch (position) {
		case "subject" -> new StatementPattern(endpoint, predicate, object);
		case "predicate" -> new StatementPattern(subject, endpoint, object);
		case "object" -> new StatementPattern(subject, predicate, endpoint);
		case "context" -> new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, subject, predicate, object,
				endpoint);
		default -> throw new IllegalArgumentException(position);
		};
	}

