	private BindingSetAssignment emptyServiceValues() {
		BindingSetAssignment provider = new BindingSetAssignment();
		provider.setBindingNames(Set.of("service"));
		provider.setBindingSets(List.of());
		return provider;
	}

	private BindingSetAssignment emptyDriver() {
		BindingSetAssignment driver = new BindingSetAssignment();
		driver.setBindingNames(Set.of("driver"));
		driver.setBindingSets(List.of());
		return driver;
	}

	private TupleExpr filteredEmptyServiceProvider() {
		Extension provider = new Extension(new SingletonSet(), new ExtensionElem(
				new ValueConstant(repository.getValueFactory().createIRI("urn:fail:filtered-empty")), "service"));
		return new Filter(provider, new ValueConstant(repository.getValueFactory().createLiteral(false)));
	}

	private TupleExpr localServiceJoin(TupleExpr provider, String shape, boolean silent) {
		return localServiceJoin(provider, shape, silent, null);
	}

	private TupleExpr localServiceJoin(TupleExpr provider, String shape, boolean silent, String endpoint) {
		TupleExpr right = filteredService(silent, endpoint);
		if (shape.equals("join")) {
			right = new Join(new SingletonSet(), right);
		} else if (shape.equals("union")) {
			right = new Union(right, filteredService(silent, endpoint));
		}
		return new Join(provider, right);
	}

	private TupleExpr filteredService(boolean silent, String endpoint) {
		StatementPattern body = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		Var ref = endpoint == null ? Var.of("service")
				: new Var("service", repository.getValueFactory().createIRI(endpoint));
		Service service = new Service(ref, body, "?s ?p ?o .", Map.of(), null, silent);
		return new Filter(service, new ValueConstant(repository.getValueFactory().createLiteral(true)));
	}

